  boxNode(660,222,560,44,"讲者补的那个更宽的点","r");
  note("「它有点太生硬了」⇒ 「它听起来不是超级友好」",940,292,"r");
  note("★★ 「而问这个问题的人，可能很爱泰迪熊 —— 所以你可能想用一种温和的方式告诉他们」",640,336,"g");
